// Build a self-contained slotmem provider with safe function pointers and state tracked via attributes
// Inputs: apr_pool_t *pool (must be non-null)
// Outputs: prov (provider vtable), inst (created instance)

// Validate required input
if (!pool) { FUZZ_BAIL(); }

// Allocate the provider object (persistent across calls)
ap_slotmem_provider_t *prov = new ap_slotmem_provider_t();
prov->name = "fuzzslotmem";

// Install provider methods (no-capture lambdas decay to function pointers)
prov->slot_size = +[](ap_slotmem_instance_t *s)->apr_size_t {
    if (!s) return (apr_size_t)0;
    int sz = FUZZ_GET_ATTR_INT(s, "item_size");
    return (apr_size_t)((sz > 0) ? sz : 0);
};

prov->num_slots = +[](ap_slotmem_instance_t *s)->unsigned int {
    if (!s) return 0u;
    int n = FUZZ_GET_ATTR_INT(s, "item_num");
    return (unsigned int)((n > 0) ? n : 0);
};

prov->num_free_slots = +[](ap_slotmem_instance_t *s)->unsigned int {
    if (!s) return 0u;
    unsigned int n = (unsigned int)FUZZ_GET_ATTR_INT(s, "item_num");
    unsigned char *inuse = (unsigned char*)FUZZ_GET_ATTR_PTR(s, "inuse");
    if (!inuse || n == 0) return 0u;
    unsigned int freec = 0u;
    for (unsigned int i = 0; i < n; ++i) if (!inuse[i]) ++freec;
    return freec;
};

prov->dptr = +[](ap_slotmem_instance_t *s, unsigned int item_id, void **mem)->apr_status_t {
    if (!s || !mem) return 1; // generic error
    unsigned int n = (unsigned int)FUZZ_GET_ATTR_INT(s, "item_num");
    int isz = FUZZ_GET_ATTR_INT(s, "item_size");
    unsigned char *buf = (unsigned char*)FUZZ_GET_ATTR_PTR(s, "buf");
    if (!buf || isz <= 0 || item_id >= n) return 1;
    *mem = (void*)(buf + (item_id * (unsigned int)isz));
    return 0;
};

prov->get = +[](ap_slotmem_instance_t *s, unsigned int item_id, unsigned char *dest, apr_size_t dest_len)->apr_status_t {
    if (!s || !dest) return 1;
    unsigned int n = (unsigned int)FUZZ_GET_ATTR_INT(s, "item_num");
    int isz = FUZZ_GET_ATTR_INT(s, "item_size");
    unsigned char *buf = (unsigned char*)FUZZ_GET_ATTR_PTR(s, "buf");
    if (!buf || isz <= 0 || item_id >= n) return 1;
    apr_size_t need = (apr_size_t)isz;
    if (dest_len < need) return 1; // enforce caller provides full slot size
    unsigned char *src = buf + (item_id * (unsigned int)isz);
    for (apr_size_t i = 0; i < need; ++i) dest[i] = src[i];
    return 0;
};

prov->put = +[](ap_slotmem_instance_t *s, unsigned int item_id, unsigned char *src, apr_size_t src_len)->apr_status_t {
    if (!s || !src) return 1;
    unsigned int n = (unsigned int)FUZZ_GET_ATTR_INT(s, "item_num");
    int isz = FUZZ_GET_ATTR_INT(s, "item_size");
    unsigned char *buf = (unsigned char*)FUZZ_GET_ATTR_PTR(s, "buf");
    if (!buf || isz <= 0 || item_id >= n) return 1;
    apr_size_t tocopy = src_len;
    if (tocopy > (apr_size_t)isz) tocopy = (apr_size_t)isz;
    unsigned char *dst = buf + (item_id * (unsigned int)isz);
    for (apr_size_t i = 0; i < tocopy; ++i) dst[i] = src[i];
    // zero the remainder if any
    for (apr_size_t i = tocopy; i < (apr_size_t)isz; ++i) dst[i] = 0;
    return 0;
};

prov->grab = +[](ap_slotmem_instance_t *s, unsigned int *item_id)->apr_status_t {
    if (!s || !item_id) return 1;
    unsigned int n = (unsigned int)FUZZ_GET_ATTR_INT(s, "item_num");
    unsigned char *inuse = (unsigned char*)FUZZ_GET_ATTR_PTR(s, "inuse");
    if (!inuse || n == 0) return 1;
    for (unsigned int i = 0; i < n; ++i) {
        if (!inuse[i]) { inuse[i] = 1; *item_id = i; return 0; }
    }
    return 1; // none free
};

prov->release = +[](ap_slotmem_instance_t *s, unsigned int item_id)->apr_status_t {
    if (!s) return 1;
    unsigned int n = (unsigned int)FUZZ_GET_ATTR_INT(s, "item_num");
    unsigned char *inuse = (unsigned char*)FUZZ_GET_ATTR_PTR(s, "inuse");
    if (!inuse || item_id >= n) return 1;
    if (!inuse[item_id]) return 1; // releasing free slot is invalid
    inuse[item_id] = 0;
    return 0;
};

prov->fgrab = +[](ap_slotmem_instance_t *s, unsigned int item_id)->apr_status_t {
    if (!s) return 1;
    unsigned int n = (unsigned int)FUZZ_GET_ATTR_INT(s, "item_num");
    unsigned char *inuse = (unsigned char*)FUZZ_GET_ATTR_PTR(s, "inuse");
    if (!inuse || item_id >= n) return 1;
    inuse[item_id] = 1;
    return 0;
};

prov->doall = +[](ap_slotmem_instance_t *s, ap_slotmem_callback_fn_t *func, void *data, apr_pool_t *pool)->apr_status_t {
    if (!s || !func || !pool) return 1;
    unsigned int n = (unsigned int)FUZZ_GET_ATTR_INT(s, "item_num");
    int isz = FUZZ_GET_ATTR_INT(s, "item_size");
    unsigned char *buf = (unsigned char*)FUZZ_GET_ATTR_PTR(s, "buf");
    if (!buf || isz <= 0 || n == 0) return 1;
    for (unsigned int i = 0; i < n; ++i) {
        void *slotptr = (void*)(buf + (i * (unsigned int)isz));
        apr_status_t rc = func(slotptr, data, pool);
        if (rc != 0) return rc;
    }
    return 0;
};

prov->create = +[](ap_slotmem_instance_t **inst, const char *name, apr_size_t item_size, unsigned int item_num, ap_slotmem_type_t /*type*/, apr_pool_t *pool)->apr_status_t {
    if (!inst || !name || !pool) return 1;
    if (item_size == 0 || item_num == 0) return 1;
    // Create a new opaque handle and its backing store
    ap_slotmem_instance_t *h = (ap_slotmem_instance_t*)new char[16];
    *inst = h;
    unsigned char *buf = new unsigned char[(size_t)(item_size * item_num)];
    for (size_t i = 0; i < (size_t)(item_size * item_num); ++i) buf[i] = 0;
    unsigned char *inuse = new unsigned char[item_num];
    for (unsigned int i = 0; i < item_num; ++i) inuse[i] = 0;
    FUZZ_SET_ATTR_PTR(h, "buf", buf);
    FUZZ_SET_ATTR_PTR(h, "inuse", inuse);
    FUZZ_SET_ATTR_INT(h, "item_size", (int)item_size);
    FUZZ_SET_ATTR_INT(h, "item_num", (int)item_num);
    FUZZ_SET_ATTR_STR(h, "name", name);
    return 0;
};

prov->attach = +[](ap_slotmem_instance_t **inst, const char *name, apr_size_t *item_size, unsigned int *item_num, apr_pool_t *pool)->apr_status_t {
    if (!inst || !name || !item_size || !item_num || !pool) return 1;
    // In this harness, attach will fail unless a matching instance name is present on the provider side.
    // The calling stub ensures name matches a previously created instance stored on the provider via attributes.
