import os
import random
import string
from typing import List

# Data type: filesystem path
# Goal: provide interesting but valid directory path strings for apreq_temp_dir_set
# FUZZ_PARAM_STR() will read our bytes; we should encode multiple candidate paths
# in one buffer and let the fuzzer slice. We'll generate a single path per call.

_SEPS = ['/', os.sep]

_WIN_DRIVES = [f"{c}:" for c in string.ascii_uppercase]

def _rand_components(rng: random.Random, minc=1, maxc=6) -> List[str]:
    comps = []
    n = rng.randint(minc, maxc)
    # common names
    common = [
        'tmp','temp','var','log','cache','run','spool','data','work','upload','downloads',
        'httpd','apache2','nginx','fastcgi','cgi-bin','sessions','sock','locks','modules',
        'user','home','app','appdata','Local','Roaming','ProgramData','Windows','System32'
    ]
    for i in range(n):
        if rng.random() < 0.6:
            name = rng.choice(common)
        else:
            # generate safe filename chars
            letters = string.ascii_letters + string.digits + "_- ."
            ln = rng.randint(1, 12)
            name = ''.join(rng.choice(letters) for _ in range(ln)).strip()
            if not name:
                name = 'x'
        # occasionally add dot segments
        if rng.random() < 0.08:
            name = '.'
        elif rng.random() < 0.05:
            name = '..'
        comps.append(name)
    return comps

def _join_path(parts: List[str], absolute: bool, sep: str) -> str:
    if sep != '/':
        parts = [p.replace('/', sep) for p in parts]
    if absolute:
        return sep + sep.join(parts)
    return sep.join(parts)

def _make_unix_path(rng: random.Random) -> str:
    absolute = rng.random() < 0.7
    parts = _rand_components(rng)
    p = _join_path(parts, absolute, '/')
    # occasionally add trailing slash
    if rng.random() < 0.3 and not p.endswith('/'):
        p += '/'
    # sometimes put under common roots
    prefixes = ['/tmp', '/var/tmp', '/var/run', '/var/spool', '/usr/local/var', '/opt']
    if absolute and rng.random() < 0.5:
        base = rng.choice(prefixes)
        if p.startswith('/'):
            p = base + ('' if p == '/' else ('' if p == '' else (p if p == '/' else ('' if p == '' else ('' if p.startswith('/') and p == '/' else p)))))
        else:
            p = base.rstrip('/') + '/' + p
    return p

def _make_win_path(rng: random.Random) -> str:
    drive = rng.choice(_WIN_DRIVES)
    parts = _rand_components(rng)
    sep = '\\'
    path = drive + '\\' + sep.join(parts)
    if rng.random() < 0.25:
        path += '\\'
    # Env-like placeholder segments (valid strings, not expansion here)
    if rng.random() < 0.2:
        path = path.replace(parts[0], 'Temp', 1)
    return path

def _maybe_special(rng: random.Random) -> str:
    specials = [
        '.', '..', './tmp', '../temp', '/tmp', '/var/tmp/', '/var/spool/httpd',
        '/var/cache/apache2/mod_proxy_fcgi', '/run/httpd', '/opt/app/tmp',
        'tmp', 'temp', 'build/tmp', 'out/artifacts/tmp',
    ]
    return rng.choice(specials)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    choice = rng.random()
    if choice < 0.15:
        s = _maybe_special(rng)
    elif choice < 0.65:
        s = _make_unix_path(rng)
    else:
        s = _make_win_path(rng)
    # Ensure non-empty and within limit
    if not s:
        s = 'tmp'
    s = s[:4000]
    return s.encode('utf-8')
